                 //            "legalMoney": true
                 //        },
                 //        {
                 //            "coin": "USDT",
                 //            "name": "USDT",
                 //            "depositAllEnable": true,
                 //            "withdrawAllEnable": true,
                 //            "free": "0",
                 //            "locked": "0",
                 //            "transferPrecision": "8",
                 //            "transferMinQuantity": "0",
                 //            "networkList": [
                 //                {
                 //                    "addressRegex": "^0x[0-9a-fA-F]{40}$",
                 //                    "memoRegex": " ",
                 //                    "network": "ETH",
