  std::any parseTrade(std::any trade, std::any market = std::any{}) override {
    //
    // fetchTrades
    //     {
    //         "price": "89685.8",
    //         "id": "1365561108437680129",
    //         "qty": "0.000004",
    //         "quoteQty": "0.000004000000000000", // warning: report to
    //         exchange - this is not quote quantity, this is base quantity
    //         "time": "1677523569575",
    //         "isBuyerMaker": false,
    //         "isBestMatch": true
    //     },
    //
    // fetchMyTrades
    //     {
    //         "symbol": "ETHUSDT",
    //         "id": 1375426310524125185,
    //         "orderId": 1375426310415879614,
    //         "price": "1580.91",
    //         "qty": "0.01",
    //         "quoteQty": "15.8091",
    //         "commission": "0",
    //         "commissionAsset": "USDT",
    //         "time": 1678699593307,
    //         "isBuyer": false,
    //         "isMaker":false,
    //         "isBestMatch":false
    //     }
    //
    // createOrder
    //     {
    //         "price": "1579.51",
    //         "qty": "0.001899",
    //         "commission": "0",
    //         "commissionAsset": "ETH",
    //         "tradeId":1375445992035598337
    //     }
    //
    std::any marketId = this->safeString(trade, std::string("symbol"));
    market = this->safeMarket(marketId, market);
    std::any symbol = ::getValue(market, std::string("symbol"));
    std::any id =
        this->safeString2(trade, std::string("id"), std::string("tradeId"));
    std::any orderId = this->safeString(trade, std::string("orderId"));
    std::any timestamp = this->safeInteger(trade, std::string("time"));
    std::any priceString = this->safeString(trade, std::string("price"));
    std::any amountString = this->safeString(trade, std::string("qty"));
    std::any type = std::any{};
    std::any fee = ccxt::dict{};
    std::any feeCost = this->safeString(trade, std::string("commission"));
    if (isTrue(!isEqual(feeCost, std::any{}))) {
      std::any feeCurrencyId =
          this->safeString(trade, std::string("commissionAsset"));
      fee = ccxt::dict{
          {std::string("cost"), feeCost},
          {std::string("currency"), this->safeCurrencyCode(feeCurrencyId)},
      };
    }
    std::any isBuyer = this->safeBool2(trade, std::string("isBuyer"),
                                       std::string("isBuyerMaker"));
    std::any side = std::any{};
    if (isTrue(!isEqual(isBuyer, std::any{}))) {
      side = (isTrue((isEqual(isBuyer, true))) ? std::any(std::string("buy"))
                                               : std::any(std::string("sell")));
    }
    std::any isMaker = this->safeString(trade, std::string("isMaker"));
    std::any takerOrMaker = std::any{};
    if (isTrue(!isEqual(isMaker, std::any{}))) {
      takerOrMaker = (isTrue((isEqual(isMaker, std::string("true"))))
                          ? std::any(std::string("maker"))
                          : std::any(std::string("taker")));
    }
    std::any costString = std::any{};
    if (isTrue(!isEqual(orderId, std::any{}))) {
      costString = this->safeString(trade, std::string("quoteQty"));
    }
    return this->safeTrade(
        ccxt::dict{
            {std::string("id"), id},
            {std::string("order"), orderId},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("symbol"), symbol},
            {std::string("type"), type},
            {std::string("side"), side},
            {std::string("takerOrMaker"), takerOrMaker},
            {std::string("price"), priceString},
            {std::string("amount"), amountString},
            {std::string("cost"), costString},
            {std::string("fee"), fee},
            {std::string("info"), trade},
        },
        market);
  }

  /**
   * @method
   * @name coinsph#fetchBalance
   * @description query for balance and get the amount of funds available for
   * trading or funds locked in orders
   * @see https://docs.coins.ph/rest-api/#accept-the-quote
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [balance structure]{@link
   * https://docs.ccxt.com/?id=balance-structure}
   */
  std::shared_future<std::any>
  fetchBalance(std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any response = awaitValue(
                            this->privateGetOpenapiV1Account(params));
                        //
                        //     {
                        //         "accountType": "SPOT",
                        //         "balances": [
                        //             {
                        //                 "asset": "BTC",
                        //                 "free": "4723846.89208129",
                        //                 "locked": "0.00000000"
                        //             },
                        //             {
                        //                 "asset": "LTC",
                        //                 "free": "4763368.68006011",
                        //                 "locked": "0.00000000"
                        //             }
                        //         ],
                        //         "canDeposit": true,
                        //         "canTrade": true,
                        //         "canWithdraw": true,
                        //         "updateTime": "1677430932528"
                        //     }
                        //
                        return this->parseBalance(response);
                      })
        .share();
  }

  std::any parseBalance(std::any response) override {
    std::any balances =
        this->safeList(response, std::string("balances"), ccxt::list{});
    std::any result = ccxt::dict{
        {std::string("info"), response},
        {std::string("timestamp"), std::any{}},
        {std::string("datetime"), std::any{}},
    };
    for (std::any i = 0; isLessThan(i, getArrayLength(balances));
         postFixIncrement(i)) {
      std::any balance = ::getValue(balances, i);
      std::any currencyId = this->safeString(balance, std::string("asset"));
      std::any code = this->safeCurrencyCode(currencyId);
      std::any account = this->account();
      ::setValue(account, std::string("free"),
                 this->safeString(balance, std::string("free")));
      ::setValue(account, std::string("used"),
                 this->safeString(balance, std::string("locked")));
      if (isTrue(!isEqual(code, std::any{}))) {
        ::setValue(result, code, account);
      }
    }
    return this->safeBalance(result);
  }

  /**
   * @method
   * @name coinsph#createOrder
   * @description create a trade order
   * @see https://docs.coins.ph/rest-api/#new-order--trade
   * @param {string} symbol unified symbol of the market to create an order in
   * @param {string} type 'market', 'limit', 'stop_loss', 'take_profit',
   * 'stop_loss_limit', 'take_profit_limit' or 'limit_maker'
   * @param {string} side 'buy' or 'sell'
   * @param {float} amount how much of currency you want to trade in units of
   * base currency
   * @param {float} [price] the price at which the order is to be fulfilled, in
   * units of the quote currency, ignored in market orders
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {float} [params.cost] the quote quantity that can be used as an
   * alternative for the amount for market buy orders
   * @param {bool} [params.test] set to true to test an order, no order will be
   * created but the request will be validated
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  createOrder(std::any symbol, std::any type, std::any side, std::any amount,
              std::any price = std::any{},
              std::any params = ccxt::dict{}) override {
    return std::
        async(std::launch::deferred,
              [=]() mutable -> std::any {
                // todo: add test order low priority
                if (isTrue(isEqual(this->markets, std::any{}))) {
                  awaitValue(this->loadMarkets());
                }
                std::any market = this->market(symbol);
                std::any testOrder =
                    this->safeBool(params, std::string("test"), false);
                params = this->omit(params, std::string("test"));
                std::any orderType =
                    this->safeString(params, std::string("type"), type);
                orderType = this->encodeOrderType(orderType);
                params = this->omit(params, std::string("type"));
                std::any orderSide = this->encodeOrderSide(side);
                std::any request = ccxt::dict{
                    {std::string("symbol"),
                     ::getValue(market, std::string("id"))},
                    {std::string("type"), orderType},
                    {std::string("side"), orderSide},
                };
                std::any options = this->safeValue(
                    this->options, std::string("createOrder"), ccxt::dict{});
                std::any newOrderRespType = this->safeValue(
                    options, std::string("newOrderRespType"), ccxt::dict{});
                // if limit order
                if (isTrue(
                        isTrue(isTrue(isTrue(isEqual(orderType,
                                                     std::string("LIMIT"))) ||
                                      isTrue(isEqual(
                                          orderType,
                                          std::string("STOP_LOSS_LIMIT")))) ||
                               isTrue(isEqual(
                                   orderType,
                                   std::string("TAKE_PROFIT_LIMIT")))) ||
                        isTrue(
                            isEqual(orderType, std::string("LIMIT_MAKER"))))) {
                  if (isTrue(isEqual(price, std::any{}))) {
                    throw ArgumentsRequired(toString(
                        add(add(add(this->id,
                                    std::string(" createOrder() requires a "
                                                "price argument for a ")),
                                type),
                            std::string(" order"))));
                  }
                  newOrderRespType =
                      this->safeString(newOrderRespType, std::string("limit"),
                                       std::string("FULL"));
                  ::setValue(request, std::string("price"),
                             this->priceToPrecision(symbol, price));
                  ::setValue(request, std::string("quantity"),
                             this->amountToPrecision(symbol, amount));
                  if (isTrue(!isEqual(orderType, std::string("LIMIT_MAKER")))) {
                    ::setValue(request, std::string("timeInForce"),
                               this->safeString(options,
                                                std::string("timeInForce"),
                                                std::string("GTC")));
                  }
                } else if (isTrue(
                               isTrue(
                                   isTrue(isEqual(orderType,
                                                  std::string("MARKET"))) ||
                                   isTrue(isEqual(orderType,
                                                  std::string("STOP_LOSS")))) ||
                               isTrue(isEqual(orderType,
                                              std::string("TAKE_PROFIT"))))) {
                  newOrderRespType =
                      this->safeString(newOrderRespType, std::string("market"),
                                       std::string("FULL"));
                  if (isTrue(isEqual(orderSide, std::string("SELL")))) {
                    ::setValue(request, std::string("quantity"),
                               this->amountToPrecision(symbol, amount));
                  } else if (isTrue(isEqual(orderSide, std::string("BUY")))) {
                    std::any quoteAmount = std::any{};
                    std::any createMarketBuyOrderRequiresPrice = true;
                    std::any createMarketBuyOrderRequiresPriceparamsVariable =
                        this->handleOptionAndParams(
                            params, std::string("createOrder"),
                            std::string("createMarketBuyOrderRequiresPrice"),
                            true);
                    createMarketBuyOrderRequiresPrice = ::getValue(
                        createMarketBuyOrderRequiresPriceparamsVariable, 0);
                    params = ::getValue(
                        createMarketBuyOrderRequiresPriceparamsVariable, 1);
                    std::any cost =
                        this->safeNumber2(params, std::string("cost"),
                                          std::string("quoteOrderQty"));
                    params = this->omit(params, std::string("cost"));
                    if (isTrue(!isEqual(cost, std::any{}))) {
                      quoteAmount = this->costToPrecision(symbol, cost);
                    } else if (isTrue(createMarketBuyOrderRequiresPrice)) {
                      if (isTrue(isEqual(price, std::any{}))) {
                        throw InvalidOrder(toString(add(
                            this->id,
                            std::string(
                                " createOrder() requires the price argument "
                                "for market buy orders to calculate the total "
                                "cost to spend (amount * price), alternatively "
                                "set the createMarketBuyOrderRequiresPrice "
                                "option or param to false and pass the cost to "
                                "spend in the amount argument"))));
                      } else {
                        std::any amountString = this->numberToString(amount);
                        std::any priceString = this->numberToString(price);
                        std::any costRequest =
                            ccxt::Precise::stringMul(amountString, priceString);
                        quoteAmount =
                            this->costToPrecision(symbol, costRequest);
                      }
                    } else {
                      quoteAmount = this->costToPrecision(symbol, amount);
                    }
                    ::setValue(request, std::string("quoteOrderQty"),
                               quoteAmount);
                  }
                }
                if (isTrue(
                        isTrue(
                            isTrue(isTrue(isEqual(orderType,
                                                  std::string("STOP_LOSS"))) ||
                                   isTrue(isEqual(
                                       orderType,
                                       std::string("STOP_LOSS_LIMIT")))) ||
                            isTrue(isEqual(orderType,
                                           std::string("TAKE_PROFIT")))) ||
                        isTrue(isEqual(orderType,
                                       std::string("TAKE_PROFIT_LIMIT"))))) {
                  std::any triggerPrice =
                      this->safeString2(params, std::string("triggerPrice"),
                                        std::string("stopPrice"));
                  if (isTrue(isEqual(triggerPrice, std::any{}))) {
                    throw InvalidOrder(toString(add(
                        this->id,
                        std::string(
                            " createOrder () requires a triggerPrice or "
                            "stopPrice param for stop_loss, take_profit, "
                            "stop_loss_limit, and take_profit_limit orders"))));
                  }
                  ::setValue(request, std::string("stopPrice"),
                             this->priceToPrecision(symbol, triggerPrice));
                }
                ::setValue(request, std::string("newOrderRespType"),
                           newOrderRespType);
                params = this->omit(
                    params, std::string("price"), std::string("stopPrice"),
                    std::string("triggerPrice"), std::string("quantity"),
                    std::string("quoteOrderQty"));
                std::any response = ccxt::dict{};
                if (isTrue(isEqual(testOrder, true))) {
                  response = awaitValue(this->privatePostOpenapiV1OrderTest(
                      this->extend(request, params)));
                } else {
                  response = awaitValue(this->privatePostOpenapiV1Order(
                      this->extend(request, params)));
                }
                //
                //     {
                //         "symbol": "ETHUSDT",
                //         "orderId": "1375407140139731486",
                //         "clientOrderId": "1375407140139733169",
                //         "transactTime": "1678697308023",
                //         "price": "1600",
                //         "origQty": "0.02",
                //         "executedQty": "0.02",
                //         "cummulativeQuoteQty": "31.9284",
                //         "status": "FILLED",
                //         "timeInForce": "GTC",
                //         "type": "LIMIT",
                //         "side": "BUY",
                //         "stopPrice": "0",
                //         "origQuoteOrderQty": "0",
                //         "fills": [
                //             {
                //                 "price": "1596.42",
                //                 "qty": "0.02",
                //                 "commission": "0",
                //                 "commissionAsset": "ETH",
                //                 "tradeId": "1375407140281532417"
                //             }
                //         ]
                //     },
                //
                return this->parseOrder(response, market);
              })
            .share();
  }

  /**
   * @method
   * @name coinsph#fetchOrder
   * @description fetches information on an order made by the user
   * @see https://docs.coins.ph/rest-api/#query-order-user_data
   * @param {int|string} id order id
   * @param {string} symbol not used by fetchOrder ()
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} An [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  fetchOrder(std::any id, std::any symbol = std::any{},
             std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any request = ccxt::dict{};
                 std::any clientOrderId =
                     this->safeValue2(params, std::string("origClientOrderId"),
                                      std::string("clientOrderId"));
                 if (isTrue(!isEqual(clientOrderId, std::any{}))) {
                   ::setValue(request, std::string("origClientOrderId"),
                              clientOrderId);
                 } else {
                   ::setValue(request, std::string("orderId"), id);
                 }
                 params = this->omit(
                     params, ccxt::list{std::string("clientOrderId"),
                                        std::string("origClientOrderId")});
                 std::any response = awaitValue(this->privateGetOpenapiV1Order(
                     this->extend(request, params)));
                 return this->parseOrder(response);
               })
        .share();
  }

  /**
   * @method
   * @name coinsph#fetchOpenOrders
   * @description fetch all unfilled currently open orders
   * @see https://docs.coins.ph/rest-api/#current-open-orders-user_data
   * @param {string} symbol unified market symbol
   * @param {int} [since] the earliest time in ms to fetch open orders for
   * @param {int} [limit] the maximum number of  open orders structures to
   * retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  fetchOpenOrders(std::any symbol = std::any{}, std::any since = std::any{},
                  std::any limit = std::any{},
                  std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any market = std::any{};
                        std::any request = ccxt::dict{};
                        if (isTrue(!isEqual(symbol, std::any{}))) {
                          market = this->market(symbol);
                          ::setValue(request, std::string("symbol"),
                                     ::getValue(market, std::string("id")));
                        }
                        std::any response =
                            awaitValue(this->privateGetOpenapiV1OpenOrders(
                                this->extend(request, params)));
                        return this->parseOrders(response, market, since,
                                                 limit);
                      })
        .share();
  }

  /**
   * @method
   * @name coinsph#fetchClosedOrders
   * @description fetches information on multiple closed orders made by the user
   * @see https://docs.coins.ph/rest-api/#history-orders-user_data
   * @param {string} symbol unified market symbol of the market orders were made
   * in
   * @param {int} [since] the earliest time in ms to fetch orders for
   * @param {int} [limit] the maximum number of order structures to retrieve
   * (default 500, max 1000)
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  fetchClosedOrders(std::any symbol = std::any{}, std::any since = std::any{},
                    std::any limit = std::any{},
                    std::any params = ccxt::dict{}) override {
    return std::
        async(std::launch::deferred,
              [=]() mutable -> std::any {
                if (isTrue(isEqual(symbol, std::any{}))) {
                  throw ArgumentsRequired(toString(add(
                      this->id,
                      std::string(
                          " fetchClosedOrders() requires a symbol argument"))));
                }
                if (isTrue(isEqual(this->markets, std::any{}))) {
                  awaitValue(this->loadMarkets());
                }
                std::any market = this->market(symbol);
                std::any request = ccxt::dict{
                    {std::string("symbol"),
                     ::getValue(market, std::string("id"))},
                };
                if (isTrue(!isEqual(since, std::any{}))) {
                  ::setValue(request, std::string("startTime"), since);
                  // since work properly only when it is "younger" than last
                  // 'limit' order
                  ::setValue(request, std::string("limit"), 1000);
                } else if (isTrue(!isEqual(limit, std::any{}))) {
                  ::setValue(request, std::string("limit"), limit);
                }
                std::any response =
                    awaitValue(this->privateGetOpenapiV1HistoryOrders(
                        this->extend(request, params)));
                return this->parseOrders(response, market, since, limit);
              })
            .share();
  }

  /**
   * @method
   * @name coinsph#cancelOrder
   * @description cancels an open order
   * @see https://docs.coins.ph/rest-api/#cancel-order-trade
   * @param {string} id order id
   * @param {string} symbol not used by cancelOrder ()
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} An [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  cancelOrder(std::any id, std::any symbol = std::any{},
              std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any request = ccxt::dict{};
                 std::any clientOrderId =
                     this->safeValue2(params, std::string("origClientOrderId"),
                                      std::string("clientOrderId"));
                 if (isTrue(!isEqual(clientOrderId, std::any{}))) {
                   ::setValue(request, std::string("origClientOrderId"),
                              clientOrderId);
                 } else {
                   ::setValue(request, std::string("orderId"), id);
                 }
                 params = this->omit(
                     params, ccxt::list{std::string("clientOrderId"),
                                        std::string("origClientOrderId")});
                 std::any response =
                     awaitValue(this->privateDeleteOpenapiV1Order(
                         this->extend(request, params)));
                 return this->parseOrder(response);
               })
        .share();
  }

  /**
   * @method
   * @name coinsph#cancelAllOrders
   * @description cancel open orders of market
   * @see
   * https://docs.coins.ph/rest-api/#cancel-all-open-orders-on-a-symbol-trade
   * @param {string} symbol unified market symbol
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  cancelAllOrders(std::any symbol = std::any{},
                  std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(symbol, std::any{}))) {
                   throw ArgumentsRequired(toString(add(
                       this->id,
                       std::string(
                           " cancelAllOrders() requires a symbol argument"))));
                 }
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = std::any{};
                 std::any request = ccxt::dict{};
                 if (isTrue(!isEqual(symbol, std::any{}))) {
                   market = this->market(symbol);
                   ::setValue(request, std::string("symbol"),
                              ::getValue(market, std::string("id")));
                 }
                 std::any response =
                     awaitValue(this->privateDeleteOpenapiV1OpenOrders(
                         this->extend(request, params)));
                 return this->parseOrders(response, market);
               })
        .share();
  }

  std::any parseOrder(std::any order, std::any market = std::any{}) override {
    //
    // createOrder POST /openapi/v1/order
    //     {
    //         "symbol": "ETHUSDT",
    //         "orderId": 1375445991893797391,
    //         "clientOrderId": "1375445991893799115",
    //         "transactTime": 1678701939513,
    //         "price": "0",
    //         "origQty": "0",
    //         "executedQty": "0.001899",
    //         "cummulativeQuoteQty": "2.99948949",
    //         "status": "FILLED",
    //         "timeInForce": "GTC",
    //         "type": "MARKET",
    //         "side": "BUY",
    //         "stopPrice": "0",
    //         "origQuoteOrderQty": "3",
    //         "fills": [
    //             {
    //                 "price": "1579.51",
    //                 "qty": "0.001899",
    //                 "commission": "0",
    //                 "commissionAsset": "ETH",
    //                 "tradeId":1375445992035598337
    //             }
    //         ]
    //     }
    //
    // fetchOrder GET /openapi/v1/order
    // fetchOpenOrders GET /openapi/v1/openOrders
    // fetchClosedOrders GET /openapi/v1/historyOrders
    // cancelAllOrders DELETE /openapi/v1/openOrders
    //     {
    //         "symbol": "DOGEPHP",
    //         "orderId":1375465375097982423,
    //         "clientOrderId": "1375465375098001241",
    //         "price": "0",
    //         "origQty": "0",
    //         "executedQty": "13",
    //         "cummulativeQuoteQty": "49.621",
    //         "status": "FILLED",
    //         "timeInForce": "GTC",
    //         "type": "MARKET",
    //         "side": "BUY",
    //         "stopPrice": "0",
    //         "time":1678704250171,
    //         "updateTime":1678704250256,
    //         "isWorking":false,
    //         "origQuoteOrderQty": "50"
    //     }
    //
    // cancelOrder DELETE /openapi/v1/order
    //     {
    //         "symbol": "ETHPHP",
    //         "orderId":1375609441915774332,
    //         "clientOrderId": "1375609441915899557",
    //         "price": "96000",
    //         "origQty": "0.001",
    //         "executedQty": "0",
    //         "cummulativeQuoteQty": "0",
    //         "status": "CANCELED",
    //         "timeInForce": "GTC",
    //         "type": "LIMIT",
    //         "side": "SELL",
    //         "stopPrice": "0",
    //         "origQuoteOrderQty": "0"
    //     }
    //
    std::any id = this->safeString(order, std::string("orderId"));
    std::any marketId = this->safeString(order, std::string("symbol"));
    market = this->safeMarket(marketId, market);
    std::any timestamp = this->safeInteger2(order, std::string("time"),
                                            std::string("transactTime"));
    std::any trades = this->safeValue(order, std::string("fills"));
    std::any triggerPrice = this->safeString(order, std::string("stopPrice"));
    if (isTrue(ccxt::Precise::stringEq(triggerPrice, std::string("0")))) {
      triggerPrice = std::any{};
    }
    return this->safeOrder(
        ccxt::dict{
            {std::string("id"), id},
            {std::string("clientOrderId"),
             this->safeString(order, std::string("clientOrderId"))},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("lastTradeTimestamp"), std::any{}},
            {std::string("status"), this->parseOrderStatus(this->safeString(
                                        order, std::string("status")))},
            {std::string("symbol"), ::getValue(market, std::string("symbol"))},
            {std::string("type"), this->parseOrderType(this->safeString(
                                      order, std::string("type")))},
            {std::string("timeInForce"),
             this->parseOrderTimeInForce(
                 this->safeString(order, std::string("timeInForce")))},
            {std::string("side"), this->parseOrderSide(this->safeString(
                                      order, std::string("side")))},
            {std::string("price"),
             this->safeString(order, std::string("price"))},
            {std::string("triggerPrice"), triggerPrice},
            {std::string("average"), std::any{}},
            {std::string("amount"),
             this->safeString(order, std::string("origQty"))},
            {std::string("cost"),
             this->safeString(order, std::string("cummulativeQuoteQty"))},
            {std::string("filled"),
             this->safeString(order, std::string("executedQty"))},
            {std::string("remaining"), std::any{}},
            {std::string("fee"), std::any{}},
            {std::string("fees"), std::any{}},
            {std::string("trades"), trades},
            {std::string("info"), order},
        },
        market);
  }

  virtual std::any parseOrderSide(std::any status) {
    std::any statuses = ccxt::dict{
        {std::string("BUY"), std::string("buy")},
        {std::string("SELL"), std::string("sell")},
    };
    if (isTrue(isEqual(status, std::any{}))) {
      return std::any{};
    }
    return this->safeString(statuses, status, status);
  }

